window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-98a3e55d60a452f3"]={"versions": [{"id": "FIG-98a3e55d60a452f3", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für Hardware-Ressourcen einer ECU im Rahmen des AUTOSAR-Resource-Templates (AUTOSAR Classic Platform). Das Diagramm definiert die strukturelle Modellierung von Hardware-Elementen, Hardware-Ports und deren logische Zuordnung zu Software-Komponenten (ECU-Abstraktion).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert folgende Entitäten, Attribute und Relationen:</p>\n<ul class=\"fig-list\">\n<li><strong>HWElement</strong> (<code>«ARElement»</code>, abstrakt/kursiv):</li>\n<li>Attribut: <code>+ standbyCurrent: Float [0..1]</code></li>\n<li>Komposition zu <code>HWPort</code>: <code>+ports</code> mit Multiplizität <code>1..*</code> (schwarze Raute bei <code>HWElement</code>).</li>\n<li><strong>HWElementContainer</strong>:</li>\n<li>Spezialisiert <code>HWElement</code> per Generalisierung (Vererbung).</li>\n<li>Komposition auf sich selbst bzw. <code>HWElement</code>: Rolle <code>+containedElements</code> mit Multiplizität <code>1..*</code> (schwarze Raute bei <code>HWElementContainer</code>).</li>\n<li><strong>ECU</strong>:</li>\n<li>Spezialisiert <code>HWElementContainer</code> per Generalisierung.</li>\n<li>Assoziation <code>+ecuAbstraction</code> mit Multiplizität <code>0..1</code> auf <code>ComponentType</code>.</li>\n<li>Ausgehende gerichtete Abhängigkeiten (gestrichelte Pfeile mit offener Spitze) zu:</li>\n<li><code>PowerDriverHWPort</code></li>\n<li><code>PeripheralHWPort</code></li>\n<li><code>CommunicationHWPort</code></li>\n<li><code>ECUCommunicationPort</code></li>\n<li><strong>ComponentType</strong> (<code>«ARElement»</code>):</li>\n<li>Ziel der gerichteten Assoziation <code>+ecuAbstraction</code> ausgehend von <code>ECU</code>.</li>\n<li><strong>HWPort</strong> (<code>«Identifiable»</code>, abstrakt/kursiv):</li>\n<li>Attribut: <code>+ direction: Enumeration{in, out, inout}</code></li>\n<li><strong>PowerDriv erHWPort</strong>:</li>\n<li>Spezialisiert <code>HWPort</code> per Generalisierung.</li>\n<li>Attribute:</li>\n<li><code>+ pwmMaxFrequency: Float [0..1]</code></li>\n<li><code>+ pwmMinOnTime: Float [0..1]</code></li>\n<li><code>+ pwmMinOffTime: Float [0..1]</code></li>\n<li><strong>PeripheralHWPort</strong>:</li>\n<li>Spezialisiert <code>HWPort</code> per Generalisierung.</li>\n<li>Attribute:</li>\n<li><code>+ inversion: Boolean [0..1]</code></li>\n<li><code>+ wakeUpCapability: Boolean [0..1]</code></li>\n<li><code>+ powerOnCapability: Boolean [0..1]</code></li>\n<li><strong>CommunicationHWPort</strong>:</li>\n<li>Spezialisiert <code>PeripheralHWPort</code> per Generalisierung.</li>\n<li><strong>ECUCommunicationPort</strong>:</li>\n<li>Spezialisiert <code>CommunicationHWPort</code> per Generalisierung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm (Metamodell). Es werden keine dynamischen Verhaltensweisen, Nachrichtenaustausche, Zustandsübergänge oder Sequenzabläufe dargestellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Metamodell schreibt verbindlich vor:</p>\n<ul class=\"fig-list\">\n<li>Jedes <code>HWElement</code> aggregiert mindestens einen <code>HWPort</code> (<code>1..*</code>).</li>\n<li>Ein <code>HWElementContainer</code> enthält mindestens ein weiteres <code>HWElement</code> (<code>1..*</code>).</li>\n<li>Eine <code>ECU</code> kann optional höchstens einer <code>ComponentType</code>-Instanz über die Rolle <code>+ecuAbstraction</code> zugeordnet sein (<code>0..1</code>).</li>\n<li>Alle Port-spezifischen Attribute bezüglich PWM-Charakteristik (<code>pwmMaxFrequency</code>, <code>pwmMinOnTime</code>, <code>pwmMinOffTime</code>), elektrischer Eigenschaften (<code>inversion</code>, <code>wakeUpCapability</code>, <code>powerOnCapability</code>) sowie des Ruhestroms (<code>standbyCurrent</code>) besitzen die Kardinalität <code>[0..1]</code> und sind somit optional.</li>\n<li>Die Signalrichtung jedes <code>HWPort</code> ist über die Enumeration <code>{in, out, inout}</code> verpflichtend zu spezifizieren.</li>\n</ul>"}, {"id": "FIG-876394e9a2bb9ec8", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für Hardware-Ressourcen einer ECU im Rahmen des AUTOSAR-Resource-Templates (AUTOSAR Classic Platform). Das Diagramm definiert die strukturelle Modellierung von Hardware-Elementen, Hardware-Ports und deren logische Zuordnung zu Software-Komponenten (ECU-Abstraktion).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert folgende Entitäten, Attribute und Relationen:</p>\n<ul class=\"fig-list\">\n<li><strong>HWElement</strong> (<code>«ARElement»</code>, abstrakt/kursiv):</li>\n<li>Attribut: <code>+ standbyCurrent: Float [0..1]</code></li>\n<li>Komposition zu <code>HWPort</code>: <code>+ports</code> mit Multiplizität <code>1..*</code> (schwarze Raute bei <code>HWElement</code>).</li>\n<li><strong>HWElementContainer</strong>:</li>\n<li>Spezialisiert <code>HWElement</code> per Generalisierung (Vererbung).</li>\n<li>Komposition auf sich selbst bzw. <code>HWElement</code>: Rolle <code>+containedElements</code> mit Multiplizität <code>1..*</code> (schwarze Raute bei <code>HWElementContainer</code>).</li>\n<li><strong>ECU</strong>:</li>\n<li>Spezialisiert <code>HWElementContainer</code> per Generalisierung.</li>\n<li>Assoziation <code>+ecuAbstraction</code> mit Multiplizität <code>0..1</code> auf <code>ComponentType</code>.</li>\n<li>Ausgehende gerichtete Abhängigkeiten (gestrichelte Pfeile mit offener Spitze) zu:</li>\n<li><code>PowerDriverHWPort</code></li>\n<li><code>PeripheralHWPort</code></li>\n<li><code>CommunicationHWPort</code></li>\n<li><code>ECUCommunicationPort</code></li>\n<li><strong>ComponentType</strong> (<code>«ARElement»</code>):</li>\n<li>Ziel der gerichteten Assoziation <code>+ecuAbstraction</code> ausgehend von <code>ECU</code>.</li>\n<li><strong>HWPort</strong> (<code>«Identifiable»</code>, abstrakt/kursiv):</li>\n<li>Attribut: <code>+ direction: Enumeration{in, out, inout}</code></li>\n<li><strong>PowerDriverHWPort</strong>:</li>\n<li>Spezialisiert <code>HWPort</code> per Generalisierung.</li>\n<li>Attribute:</li>\n<li><code>+ pwmMaxFrequency: Float [0..1]</code></li>\n<li><code>+ pwmMinOnTime: Float [0..1]</code></li>\n<li><code>+ pwmMinOffTime: Float [0..1]</code></li>\n<li><strong>PeripheralHWPort</strong>:</li>\n<li>Spezialisiert <code>HWPort</code> per Generalisierung.</li>\n<li>Attribute:</li>\n<li><code>+ inversion: Boolean [0..1]</code></li>\n<li><code>+ wakeUpCapability: Boolean [0..1]</code></li>\n<li><code>+ powerOnCapability: Boolean [0..1]</code></li>\n<li><strong>CommunicationHWPort</strong>:</li>\n<li>Spezialisiert <code>PeripheralHWPort</code> per Generalisierung.</li>\n<li><strong>ECUCommunicationPort</strong>:</li>\n<li>Spezialisiert <code>CommunicationHWPort</code> per Generalisierung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm (Metamodell). Es werden keine dynamischen Verhaltensweisen, Nachrichtenaustausche, Zustandsübergänge oder Sequenzabläufe dargestellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Metamodell schreibt verbindlich vor:</p>\n<ul class=\"fig-list\">\n<li>Jedes <code>HWElement</code> aggregiert mindestens einen <code>HWPort</code> (<code>1..*</code>).</li>\n<li>Ein <code>HWElementContainer</code> enthält mindestens ein weiteres <code>HWElement</code> (<code>1..*</code>).</li>\n<li>Eine <code>ECU</code> kann optional höchstens einer <code>ComponentType</code>-Instanz über die Rolle <code>+ecuAbstraction</code> zugeordnet sein (<code>0..1</code>).</li>\n<li>Alle Port-spezifischen Attribute bezüglich PWM-Charakteristik (<code>pwmMaxFrequency</code>, <code>pwmMinOnTime</code>, <code>pwmMinOffTime</code>), elektrischer Eigenschaften (<code>inversion</code>, <code>wakeUpCapability</code>, <code>powerOnCapability</code>) sowie des Ruhestroms (<code>standbyCurrent</code>) besitzen die Kardinalität <code>[0..1]</code> und sind somit optional.</li>\n<li>Die Signalrichtung jedes <code>HWPort</code> ist über die Enumeration <code>{in, out, inout}</code> verpflichtend zu spezifizieren.</li>\n</ul>"}, {"id": "FIG-75b91443e3bc12eb", "releases": ["R3.1.5", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für Hardware-Ressourcen einer ECU im Rahmen des AUTOSAR-Resource-Templates (AUTOSAR Classic Platform). Das Diagramm definiert die strukturelle Modellierung von Hardware-Elementen, Hardware-Ports und deren logische Zuordnung zu Software-Komponenten (ECU-Abstraktion).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert folgende Entitäten, Attribute und Relationen:</p>\n<ul class=\"fig-list\">\n<li><strong>HWElement</strong> (<code>«ARElement»</code>, abstrakt/kursiv):</li>\n<li>Attribut: <code>+ standbyCurrent: Float [0..1]</code></li>\n<li>Komposition zu <code>HWPort</code>: <code>+ports</code> mit Multiplizität <code>1..*</code> (schwarze Raute bei <code>HWElement</code>).</li>\n<li><strong>HWElementContainer</strong>:</li>\n<li>Spezialisiert <code>HWElement</code> per Generalisierung (Vererbung).</li>\n<li>Komposition auf sich selbst bzw. <code>HWElement</code>: Rolle <code>+containedElements</code> mit Multiplizität <code>1..*</code> (schwarze Raute bei <code>HWElementContainer</code>).</li>\n<li><strong>ECU</strong>:</li>\n<li>Spezialisiert <code>HWElementContainer</code> per Generalisierung.</li>\n<li>Assoziation <code>+ecuAbstraction</code> mit Multiplizität <code>0..1</code> auf <code>ComponentType</code>.</li>\n<li>Ausgehende gerichtete Abhängigkeiten (gestrichelte Pfeile mit offener Spitze) zu:</li>\n<li><code>PowerDriverHWPort</code></li>\n<li><code>PeripheralHWPort</code></li>\n<li><code>CommunicationHWPort</code></li>\n<li><code>ECUCommunicationPort</code></li>\n<li><strong>ComponentType</strong> (<code>«ARElement»</code>):</li>\n<li>Ziel der gerichteten Assoziation <code>+ecuAbstraction</code> ausgehend von <code>ECU</code>.</li>\n<li><strong>HWPort</strong> (<code>«Identifiable»</code>, abstrakt/kursiv):</li>\n<li>Attribut: <code>+ direction: Enumeration{in, out, inout}</code></li>\n<li><strong>PowerDriverHWPort</strong>:</li>\n<li>Spezialisiert <code>HWPort</code> per Generalisierung.</li>\n<li>Attribute:</li>\n<li><code>+ pwmMaxFrequency: Float [0..1]</code></li>\n<li><code>+ pwmMinOnTime: Float [0..1]</code></li>\n<li><code>+ pwmMinOffTime: Float [0..1]</code></li>\n<li><strong>PeripheralHWPort</strong>:</li>\n<li>Spezialisiert <code>HWPort</code> per Generalisierung.</li>\n<li>Attribute:</li>\n<li><code>+ inversion: Boolean [0..1]</code></li>\n<li><code>+ wakeUpCapability: Boolean [0..1]</code></li>\n<li><code>+ powerOnCapability: Boolean [0..1]</code></li>\n<li><strong>CommunicationHWPort</strong>:</li>\n<li>Spezialisiert <code>PeripheralHWPort</code> per Generalisierung.</li>\n<li><strong>ECUCommunicationPort</strong>:</li>\n<li>Spezialisiert <code>CommunicationHWPort</code> per Generalisierung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm (Metamodell). Es werden keine dynamischen Verhaltensweisen, Nachrichtenaustausche, Zustandsübergänge oder Sequenzabläufe dargestellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Metamodell schreibt verbindlich vor:</p>\n<ul class=\"fig-list\">\n<li>Jedes <code>HWElement</code> aggregiert mindestens einen <code>HWPort</code> (<code>1..*</code>).</li>\n<li>Ein <code>HWElementContainer</code> enthält mindestens ein weiteres <code>HWElement</code> (<code>1..*</code>).</li>\n<li>Eine <code>ECU</code> kann optional höchstens einer <code>ComponentType</code>-Instanz über die Rolle <code>+ecuAbstraction</code> zugeordnet sein (<code>0..1</code>).</li>\n<li>Alle Port-spezifischen Attribute bezüglich PWM-Charakteristik (<code>pwmMaxFrequency</code>, <code>pwmMinOnTime</code>, <code>pwmMinOffTime</code>), elektrischer Eigenschaften (<code>inversion</code>, <code>wakeUpCapability</code>, <code>powerOnCapability</code>) sowie des Ruhestroms (<code>standbyCurrent</code>) besitzen die Kardinalität <code>[0..1]</code> und sind somit optional.</li>\n<li>Die Signalrichtung jedes <code>HWPort</code> ist über die Enumeration <code>{in, out, inout}</code> verpflichtend zu spezifizieren.</li>\n</ul>"}], "trans": [{"from": "FIG-98a3e55d60a452f3", "to": "FIG-876394e9a2bb9ec8", "fr": "R2.1.20", "tr": "R3.0.7", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Schreibweise korrigiert: Bei Klasse <code>PowerDriverHWPort</code> wurde das fälschliche Leerzeichen im Klassennamen (<code>PowerDriv erHWPort</code> zu <code>PowerDriverHWPort</code>) entfernt.</li>\n</ul>"}, {"from": "FIG-876394e9a2bb9ec8", "to": "FIG-75b91443e3bc12eb", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
